import{_ as o,a0 as l,w as r,s as d,I as t,x as e,a1 as i,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"使用 Btrfs 快照進行增量備份 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Btrfs 快照進行增量備份 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Btrfs 快照進行增量備份 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Btrfs 快照進行增量備份 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200914 Incremental backups with Btrfs snapshots","title":"使用 Btrfs 快照進行增量備份","tag":"202009","desc":""},"relativePath":"202009/20200914 Incremental backups with Btrfs snapshots.md","filePath":"[post].md"}'),h={name:"202009/20200914 Incremental backups with Btrfs snapshots.md"};function u(b,s,f,k,m,g){const a=l("Link");return r(),d("div",null,[s[18]||(s[18]=t("h1",{id:"使用-btrfs-快照進行增量備份",tabindex:"-1"},[e("使用 Btrfs 快照進行增量備份 "),t("a",{class:"header-anchor",href:"#使用-btrfs-快照進行增量備份","aria-label":"Permalink to “使用 Btrfs 快照進行增量備份”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/26/112524cppfppjpvplyjzyx.jpg",alt:""})],-1)),s[20]||(s[20]=t("p",null,[t("ruby",null,[e("快照"),t("rt",null,"snapshot")]),e("是 Btrfs 的一個有趣的功能。快照是一個子卷的副本。生成快照是立即的。然而，生成快照與執行 "),t("code",null,"rsync"),e(" 或 "),t("code",null,"cp"),e(" 不同，快照並不是一創建就會佔用空間。")],-1)),t("blockquote",null,[t("p",null,[s[1]||(s[1]=e("編者注：來自 ",-1)),i(a,{href:"https://btrfs.wiki.kernel.org/index.php/SysadminGuide#Snapshots"},{default:n(()=>[...s[0]||(s[0]=[e("BTRFS Wiki",-1)])]),_:1}),s[2]||(s[2]=e("：快照簡單的來説就是一個子卷，它使用 Btrfs 的 COW 功能與其他子卷共享其數據（和元數據）。",-1))])]),s[21]||(s[21]=p(`<p>佔用的空間將隨着原始子卷或快照本身（如果它是可寫的）的數據變化而增加。子卷中已添加/修改的文件和已刪除的文件仍然存在於快照中。這是一種方便的備份方式。</p><h3 id="使用快照進行備份" tabindex="-1">使用快照進行備份 <a class="header-anchor" href="#使用快照進行備份" aria-label="Permalink to “使用快照進行備份”">​</a></h3><p>快照駐留在子卷所在的同一磁盤上。你可以像瀏覽普通目錄一樣瀏覽它，並按照生成快照時的狀態恢復文件的副本。順便説一下，在快照子卷的同一磁盤上生成快照並不是一個理想的備份策略：如果硬盤壞了，快照也會丟失。快照的一個有趣的功能是可以將快照發送到另一個位置。快照可以被髮送到外部硬盤或通過 SSH 發送到遠程系統（目標文件系統也需要格式化為 Btrfs）。要實現這個，需要使用命令 <code>btrfs send</code> 和 <code>btrfs receive</code>。</p><h3 id="生成快照" tabindex="-1">生成快照 <a class="header-anchor" href="#生成快照" aria-label="Permalink to “生成快照”">​</a></h3><p>要使用 <code>btrfs send</code> 和 <code>btrfs receive</code> 命令，重要的是要將快照創建為只讀，而快照默認是可寫的。</p><p>下面的命令將對 <code>/home</code> 子捲進行快照。請注意 <code>-r</code> 標誌代表只讀。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume snapshot -r /home /.snapshots/home-day1</span></span></code></pre></div><p>快照的名稱可以是當前日期，而不是 <code>day1</code>，比如 <code>home-$(date +%Y%m%d)</code>。快照看起來像普通的子目錄。你可以把它們放在任何你喜歡的地方。目錄 <code>/.snapshots</code> 可能是一個不錯的選擇，以保持它們的整潔和避免混淆。</p><blockquote><p>編者注：快照不會對自己進行遞歸快照。如果你創建了一個子卷的快照，子卷所包含的每一個子卷或快照都會被映射到快照裏面的一個同名的空目錄。</p></blockquote><h3 id="使用-btrfs-send-進行備份" tabindex="-1">使用 btrfs send 進行備份 <a class="header-anchor" href="#使用-btrfs-send-進行備份" aria-label="Permalink to “使用 btrfs send 進行備份”">​</a></h3><p>在本例中，U 盤中的目標 Btrfs 卷被掛載為 <code>/run/media/user/mydisk/bk</code>。發送快照到目標卷的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs send /.snapshots/home-day1 | sudo btrfs receive /run/media/user/mydisk/bk</span></span></code></pre></div><p>這被稱為初始啓動，它相當於一個完整的備份。這個任務需要一些時間，取決於 <code>/home</code> 目錄的大小。顯然，後續的增量發送只需要更短的時間。</p><h3 id="增量備份" tabindex="-1">增量備份 <a class="header-anchor" href="#增量備份" aria-label="Permalink to “增量備份”">​</a></h3><p>快照的另一個有用的功能是能夠以增量的方式執行發送任務。讓我們再來生成一個快照。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume snapshot -r /home /.snapshots/home-day2</span></span></code></pre></div><p>為了執行增量發送任務，需要指定上一個快照作為基礎，並且這個快照必須存在於源文件和目標文件中。請注意 <code>-p</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs send -p /.snapshot/home-day1 /.snapshot/home-day2 | sudo btrfs receive /run/media/user/mydisk/bk</span></span></code></pre></div><p>再來一次（一天之後）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume snapshot -r /home /.snapshots/home-day3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo btrfs send -p /.snapshot/home-day2 /.snapshot/home-day3 | sudo btrfs receive /run/media/user/mydisk/bk</span></span></code></pre></div><h3 id="清理" tabindex="-1">清理 <a class="header-anchor" href="#清理" aria-label="Permalink to “清理”">​</a></h3><p>操作完成後，你可以保留快照。但如果你每天都執行這些操作，你可能最終會有很多快照。這可能會導致混亂，並可能會在你的磁盤上使用大量的空間。因此，如果你認為你不再需要一些快照，刪除它們是一個很好的建議。</p><p>請記住，為了執行增量發送，你至少需要最後一個快照。這個快照必須存在於源文件和目標文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume delete /.snapshot/home-day1</span></span>
<span class="line"><span>sudo btrfs subvolume delete /.snapshot/home-day2</span></span>
<span class="line"><span>sudo btrfs subvolume delete /run/media/user/mydisk/bk/home-day1</span></span>
<span class="line"><span>sudo btrfs subvolume delete /run/media/user/mydisk/bk/home-day2</span></span></code></pre></div><p>注意：第 3 天的快照被保存在源文件和目標文件中。這樣，明天（第 4 天），你就可以執行新的增量 <code>btrfs send</code>。</p><p>最後的建議是，如果 U 盤的空間很大，可以考慮在目標盤中保留多個快照，而在源盤中只保留最後一個快照。</p><hr>`,27)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),i(a,{href:"https://fedoramagazine.org/btrfs-snapshots-backup-incremental/"},{default:n(()=>[...s[3]||(s[3]=[e("https://fedoramagazine.org/btrfs-snapshots-backup-incremental/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"https://fedoramagazine.org/author/alciregi/"},{default:n(()=>[...s[5]||(s[5]=[e("Alessio",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const C=o(h,[["render",u]]);export{v as __pageData,C as default};
